cases.text:
-> implemented?(ExtensionName::H);

for (U32 i = 3; i < 32; i++){
  HPM_COUNTER_EN[i] -> HCOUNTENABLE_EN[i];
}

-> implemented?(ExtensionName::H);
implemented?(ExtensionName::Sv32) -> SV32X4_TRANSLATION;
implemented?(ExtensionName::Sv39) -> SV39X4_TRANSLATION;
implemented?(ExtensionName::Sv48) -> SV48X4_TRANSLATION;
implemented?(ExtensionName::Sv57) -> SV57X4_TRANSLATION;
-> GSTAGE_MODE_BARE;

-> implemented?(ExtensionName::Zihpm) && implemented?(ExtensionName::S);

for (U32 i = 0; i < 32; i++) {
  HPM_COUNTER_EN[i] -> SCOUNTENABLE_EN[i];
}

# "Commercial architecture IDs are allocated by each commercial vendor independently, but must have the MSB set and cannot contain zero in the remaining MXLEN-1 bits."
MXLEN == 32 -> ARCH_ID_VALUE != 32'h80000000;
MXLEN == 32 -> ARCH_ID_VALUE <= 32'hffffffff;
MXLEN == 64 -> ARCH_ID_VALUE != 64'h8000000000000000;

# if host is 32 bit, then one of Bare or Sv32X4 must be supported
$array_includes?(SXLEN, 32) && !SV32X4_TRANSLATION
  -> GSTAGE_MODE_BARE;

# if host is 64 bit, then one of Bare, Sv39X4, Sv48x4, or Sv57x4 must be supported
$array_includes?(SXLEN, 64) && !SV39X4_TRANSLATION && !SV48X4_TRANSLATION && !SV57X4_TRANSLATION
  -> GSTAGE_MODE_BARE;

for (U32 i = 0; i < 3; i++) {
  !implemented?(ExtensionName::Zicntr) -> !HCOUNTENABLE_EN[i];
}
for (U32 i = 3; i < 32; i++) {
  !implemented?(ExtensionName::Zihpm) -> !HCOUNTENABLE_EN[i];
}

for (U32 i = 0; i < 3; i++) {
  !implemented?(ExtensionName::Zicntr) -> !MCOUNTENABLE_EN[i];
}
for (U32 i=3; i < 32; i++) {
  !implemented?(ExtensionName::Zihpm) -> !MCOUNTENABLE_EN[i];
}

# [RULE] If there is a hardware update to mstatus.VS, then the Dirty state must be supported
implemented?(ExtensionName::V)
  -> $array_includes?(MSTATUS_VS_LEGAL_VALUES, 3);

for (U32 i = 0; i < 3; i++) {
  !implemented?(ExtensionName::Zicntr) -> !SCOUNTENABLE_EN[i];
}
for (U32 i = 3; i < 32; i++) {
  !implemented?(ExtensionName::Zihpm) -> !SCOUNTENABLE_EN[i];
}

MSTATEEN_JVT_TYPE == "read-only-0" -> SSTATEEN_JVT_TYPE == "read-only-0";
MSTATEEN_JVT_TYPE == "read-only-1" -> SSTATEEN_JVT_TYPE == "read-only-1";

HSTATEEN_JVT_TYPE == "read-only-0" -> SSTATEEN_JVT_TYPE == "read-only-0";
HSTATEEN_JVT_TYPE == "read-only-1" -> SSTATEEN_JVT_TYPE == "read-only-1";

# at least one of Bare, Sv32 must be supported
!VSSTAGE_MODE_BARE
  -> SV32_VSMODE_TRANSLATION;

# at least one of Bare, SvQQX4 must be supported
!VSSTAGE_MODE_BARE && !SV48_VSMODE_TRANSLATION && !SV57_VSMODE_TRANSLATION
  -> SV39_VSMODE_TRANSLATION;

# at least one of Bare, SvQQx4 must be supported
!GSTAGE_MODE_BARE && !SV39X4_TRANSLATION && !SV57X4_TRANSLATION
  -> SV48X4_TRANSLATION;

# at least one of Bare, SvQQX4 must be supported
!VSSTAGE_MODE_BARE && !SV39_VSMODE_TRANSLATION && !SV57_VSMODE_TRANSLATION
  -> SV48_VSMODE_TRANSLATION;

# at least one of Bare, SvQQx4 must be supported
!GSTAGE_MODE_BARE && !SV39X4_TRANSLATION && !SV48X4_TRANSLATION
  -> SV57X4_TRANSLATION;

# at least one of Bare, SvQQX4 must be supported
!VSSTAGE_MODE_BARE && !SV39_VSMODE_TRANSLATION && !SV48_VSMODE_TRANSLATION
  -> SV57_VSMODE_TRANSLATION;

# XLEN in U-mode can never be larger than XLEN in M-mode
MXLEN == 32 -> !$array_includes?(UXLEN, 64);

# If S-mode supports RV32, then U mode must also support it.
$array_includes?(SXLEN, 32) -> $array_includes?(UXLEN, 32);

# if guest is 32 bit, then one of Bare or SV32_VSMODE_TRANSLATION must be supported
$array_includes?(VSXLEN, 32) && !SV32_VSMODE_TRANSLATION
  -> VSSTAGE_MODE_BARE;

# if guest is 64 bit, then one of Bare, Sv39, Sv48, or Sv57 must be supported
$array_includes?(VSXLEN, 64) && !SV39_VSMODE_TRANSLATION && !SV48_VSMODE_TRANSLATION && !SV57_VSMODE_TRANSLATION
  -> VSSTAGE_MODE_BARE;
